        const SCHEMA_VERSION: u8 = 1;

        fn from_payloads(intent: &ReleaseIntent, validated: &ValidatedPayloadEntries) -> Result<Self, SuccessorError> {
            validated.validate_for(intent)?;
            let mut payloads = validated
                .entries
                .iter()
                .filter_map(|entry| match &entry.slot {
                    ReleaseArtifactSlot::ProductAsset {
                        target,
                        file_name,
                        provenance_policy,
                        ..
                    } => Some(MetadataPayload {
                        target: *target,
                        file_name: file_name.clone(),
                        digest: entry.digest.clone(),
                        byte_length: entry.byte_length,
                        provenance_policy: provenance_policy.clone(),
                    }),
                    _ => None,
                })
                .collect::<Vec<_>>();
            payloads.sort_by_key(|payload| payload.target);
