#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ObservedOperation {
    operation: ReleaseOperationId,
    evidence: ReleaseObservationEvidence,
    provenance: ObservationProvenance,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct CompleteObservationReceipt {
    schema_version: u8,
    intent_digest: IntentDigest,
    operations: Vec<ObservedOperation>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct CompleteObservationReceiptWire {
    schema_version: u8,
    intent_digest: IntentDigest,
    operations: Vec<ObservedOperation>,
}

struct ObservationExpectations {
    entries: BTreeMap<ReleaseArtifactSlot, (ArtifactDigest, u64)>,
    tag_annotation_digest: ArtifactDigest,
    asset_roster_digest: ArtifactDigest,
}

impl ObservationExpectations {
    fn from_manifest(intent: &ReleaseIntent, manifest: &ReleaseArtifactManifest) -> Result<Self, SuccessorError> {
        manifest.validate_for_intent(intent)?;
        let entries = manifest
            .entries
            .iter()
            .map(|entry| (entry.slot.clone(), (entry.digest.clone(), entry.byte_length)))
            .collect();
        let mut roster = CanonicalTranscript::intent_v1();
        for entry in &manifest.entries {
            if entry.slot.release().is_some() {
                roster.push_bytes("asset", serde_json::to_vec(entry).expect("closed entry serializes"));
            }
        }
        Ok(Self {
            entries,
            tag_annotation_digest: ArtifactDigest::from_bytes(format!(
                "Release {}\n",
                intent.product_release.tag()
            )),
            asset_roster_digest: ArtifactDigest::from_bytes(roster.as_bytes()),
        })
    }
}

impl CompleteObservationReceipt {
    const SCHEMA_VERSION: u8 = 1;

    fn new(
        intent: &ReleaseIntent,
        expected: &ObservationExpectations,
        operations: Vec<ObservedOperation>,
    ) -> Result<Self, SuccessorError> {
        if operations
            .iter()
            .map(|entry| &entry.operation)
            .ne(intent.operations.iter().map(|operation| &operation.id))
        {
            return Err(SuccessorError::MismatchedObservationRoster);
        }
        for entry in &operations {
            validate_evidence(intent, expected, entry)?;
        }
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            intent_digest: intent.digest.clone(),
            operations,
        })
    }

    fn validate_for_intent(
        &self,
        intent: &ReleaseIntent,
        expected: &ObservationExpectations,
    ) -> Result<(), SuccessorError> {
        if self.schema_version != Self::SCHEMA_VERSION || self.intent_digest != intent.digest {
            return Err(SuccessorError::MismatchedObservationIntent);
        }
        Self::new(intent, expected, self.operations.clone()).map(|_| ())
    }
}

impl<'de> Deserialize<'de> for CompleteObservationReceipt {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = CompleteObservationReceiptWire::deserialize(deserializer)?;
        if wire.schema_version != Self::SCHEMA_VERSION {
            return Err(serde::de::Error::custom("unsupported observation receipt schema"));
        }
        Ok(Self {
            schema_version: wire.schema_version,
            intent_digest: wire.intent_digest,
            operations: wire.operations,
        })
    }
}

fn validate_evidence(
    intent: &ReleaseIntent,
    expected: &ObservationExpectations,
    entry: &ObservedOperation,
) -> Result<(), SuccessorError> {
    match (&entry.operation, &entry.evidence) {
        (
            ReleaseOperationId::RegistryArtifactPublish {
                package,
                version,
                registry,
                slot,
            },
            ReleaseObservationEvidence::RegistryArtifact {
                schema_version: 1,
                package: evidence_package,
                version: evidence_version,
                registry: evidence_registry,
                slot: evidence_slot,
                digest,
                byte_length,
            },
        ) if package == evidence_package
            && version == evidence_version
            && registry == evidence_registry
            && slot == evidence_slot
            && expected.entries.get(slot) == Some(&(digest.clone(), *byte_length)) =>
        {
            Ok(())
        }
        (
            ReleaseOperationId::ProductTag { release, tag },
            ReleaseObservationEvidence::RemoteTag {
                schema_version: 1,
                release: evidence_release,
                name,
                target,
                annotation_digest,
            },
        ) if release == evidence_release
            && tag == name
            && target == &intent.source_commit
            && annotation_digest == &expected.tag_annotation_digest =>
        {
            Ok(())
        }
        (
            ReleaseOperationId::ForgePrepare { release, .. },
            ReleaseObservationEvidence::ForgePrepare {
                schema_version: 1,
                release: evidence_release,
                lifecycle: ForgePrepareLifecycle::Draft | ForgePrepareLifecycle::PublishedSuccessor,
            },
        ) if release == evidence_release => Ok(()),
        (
            ReleaseOperationId::ForgePublish { release, .. },
            ReleaseObservationEvidence::ForgePublish {
                schema_version: 1,
                release: evidence_release,
                asset_roster_digest,
            },
        ) if release == evidence_release && asset_roster_digest == &expected.asset_roster_digest => Ok(()),
        (
            ReleaseOperationId::ArtifactUpload { release, slot },
            ReleaseObservationEvidence::ForgeAsset {
                schema_version: 1,
                release: evidence_release,
                slot: evidence_slot,
                digest,
                byte_length,
            },
        ) if release == evidence_release
            && slot == evidence_slot
            && expected.entries.get(slot) == Some(&(digest.clone(), *byte_length)) =>
        {
            Ok(())
        }
        _ => Err(SuccessorError::MismatchedObservationEvidence),
    }
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
enum SuccessorError {
    #[error("product name `{raw}` is not canonical and safe")]
    InvalidProductName { raw: String },
    #[error("coordinated release version `{version}` is not SemVer")]
    NonSemverProductVersion { version: Box<Version> },
    #[error("coordinated release has no package versions")]
    EmptyCoordinatedRoster,
    #[error("coordinated release versions diverge: expected {expected}, found {found}")]
    DivergentCoordinatedVersion {
        expected: Box<Version>,
        found: Box<Version>,
    },
    #[error("artifact slot is unsafe")]
    UnsafeArtifactSlot,
    #[error("artifact slot provenance is invalid")]
    InvalidProvenance,
    #[error("reserved artifact file name is wrong")]
    WrongReservedFileName,
    #[error("artifact slot refers to a different product release")]
    ForeignProductRelease,
    #[error("package operation does not own its registry slot")]
    InvalidPackageOperation,
    #[error("registry artifact format does not match package ecosystem")]
    RegistryFormatMismatch,
    #[error("approved registry package roster contains a duplicate")]
    DuplicateRegistryPackage,
    #[error("registry slot is not in the approved coordinated roster")]
    RegistrySlotOutsideApprovedRoster,
    #[error("forge operations and product provenance must address one repository")]
    MismatchedForgeRepository,
    #[error("product operation does not own the coordinated product release")]
    InvalidProductOperation,
    #[error("release operation prerequisites are invalid")]
    InvalidPrerequisite,
    #[error("release operation identities are duplicated")]
    DuplicateOperation,
    DuplicateOperation,
    #[error("artifact slots are duplicated")]
    DuplicateSlot,
    #[error("artifact file names are duplicated")]
    DuplicateFileName,
    #[error("product artifact roster is not the closed supported set")]
    InvalidProductRoster,
    #[error("release operations are not in canonical topological order")]
    NonCanonicalOperationOrder,
    #[error("release operation prerequisites contain a cycle")]
    CyclicPrerequisites,
    #[error("artifact manifest differs from the intent-bound roster")]
    MismatchedManifest,
    #[error("validated payload entries are bound to a different intent")]
    MismatchedPayloadIntent,
    #[error("observation receipt is bound to a different intent or schema")]
    MismatchedObservationIntent,
    #[error("observation receipt operation roster is not canonical and exact")]
    MismatchedObservationRoster,
    #[error("observation evidence does not match its operation identity")]
    MismatchedObservationEvidence,
    #[error("distribution metadata is not canonical")]
    InvalidMetadata,
    #[error("checksum roster is not the exact payload plus metadata set")]
    InvalidChecksumRoster,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn commit() -> CommitSha {
        CommitSha::parse(&"a".repeat(40)).unwrap()
    }

    fn policy() -> ProvenancePolicy {
        ProvenancePolicy::new(
            GitHubRepository::parse("callisto-rs/callisto").unwrap(),
            ".github/workflows/callisto-release.yml",
            commit(),
        )
        .unwrap()
    }

    fn release() -> ProductReleaseId {
        ProductReleaseId::from_coordinated_versions(
            ProductName::parse("callisto").unwrap(),
            [Version::semver(1, 2, 3), Version::semver(1, 2, 3)],
        )
        .unwrap()
    }

    fn slots(release: &ProductReleaseId) -> Vec<ReleaseArtifactSlot> {
        ProductTarget::ALL
            .iter()
            .map(|target| ReleaseArtifactSlot::ProductAsset {
                release: release.clone(),
                target: *target,
                file_name: format!("callisto-{target:?}.tar.gz"),
                provenance_policy: policy(),
            })
            .chain([
                ReleaseArtifactSlot::ChecksumManifest {
                    release: release.clone(),
                    file_name: CHECKSUM_FILE_NAME.to_string(),
                    provenance_policy: policy(),
                },
                ReleaseArtifactSlot::ReleaseMetadata {
                    release: release.clone(),
                    file_name: METADATA_FILE_NAME.to_string(),
                    provenance_policy: policy(),
                },
            ])
            .collect()
    }

    fn intent() -> ReleaseIntent {
        let release = release();
        let slots = slots(&release);
        let tag = ReleaseOperationId::ProductTag {
            release: release.clone(),
            tag: release.tag(),
        };
        let prepare = ReleaseOperationId::ForgePrepare {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        let uploads = slots
            .iter()
            .map(|slot| {
                ReleaseOperation::new(
                    ReleaseOperationId::ArtifactUpload {
                        release: release.clone(),
                        slot: slot.clone(),
                    },
                    vec![prepare.clone()],
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        let publish = ReleaseOperationId::ForgePublish {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        let mut prerequisites = uploads.iter().map(|operation| operation.id.clone()).collect::<Vec<_>>();
        prerequisites.sort();
        let mut operations = vec![
            ReleaseOperation::new(tag.clone(), vec![]).unwrap(),
            ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap(),
        ];
        operations.extend(uploads);
        operations.push(ReleaseOperation::new(publish, prerequisites).unwrap());
        operations.sort_by(|left, right| left.id.cmp(&right.id));
        // Rebuild in canonical DAG order: tag, prepare, all uploads, publish.
        let mut canonical = Vec::new();
        let tag = operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
            .cloned()
            .unwrap();
        let prepare = operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
            .cloned()
            .unwrap();
        canonical.push(tag);
        canonical.push(prepare);
        canonical.extend(
            operations
                .iter()
                .filter(|operation| matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }))
                .cloned(),
        );
        canonical.sort_by(|left, right| left.id.cmp(&right.id));
        // The stable order is identity sorted among all currently-ready nodes;
        // calculate it rather than baking a variant order into the test fixture.
        let edges: BTreeMap<_, _> = canonical
            .iter()
            .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
            .chain(std::iter::once((
                operations
                    .iter()
                    .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
                    .unwrap()
                    .id
                    .clone(),
                operations
                    .iter()
                    .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
                    .unwrap()
                    .prerequisites
                    .clone(),
            )))
            .collect();
        let ordered = stable_order(&edges).unwrap();
        let lookup: BTreeMap<_, _> = operations
            .into_iter()
            .chain(canonical)
            .map(|operation| (operation.id.clone(), operation))
            .collect();
        ReleaseIntent::new(
            release,
            commit(),
            vec![],
            ordered.into_iter().map(|id| lookup[&id].clone()).collect(),
            slots,
        )
        .unwrap()
    }

    fn registry_binding() -> RegistryBindingId {
        RegistryBindingId::new(
            "cratesIo",
            RegistryBindingDigest::from_normalized_binding("https://index.crates.io/"),
        )
        .unwrap()
    }

    #[test]
    fn approved_registry_roster_is_positive_and_feeds_the_product_tag() {
        let release = release();
        let registry = registry_binding();
        let package = ReleasePackageId::parse("cargo/callisto-model").unwrap();
        let approved =
            ApprovedRegistryPackage::new(package.clone(), registry.clone(), RegistryArtifactFormat::CargoCrate)
                .unwrap();
        let reverse_package = ReleasePackageId::parse("cargo/aaa").unwrap();
        let reverse_approved = ApprovedRegistryPackage::new(
            reverse_package.clone(),
            registry.clone(),
            RegistryArtifactFormat::CargoCrate,
        )
        .unwrap();
        assert_eq!(
            serde_json::from_value::<ApprovedRegistryPackage>(serde_json::to_value(&approved).unwrap()).unwrap(),
            approved
        );
        let mut malformed_approved = serde_json::to_value(&approved).unwrap();
        malformed_approved["format"] = serde_json::Value::String("pythonWheel".to_string());
        assert!(serde_json::from_value::<ApprovedRegistryPackage>(malformed_approved).is_err());
        let registry_slot = ReleaseArtifactSlot::RegistryPackage {
            package: package.clone(),
            version: release.version.clone(),
            registry: registry.clone(),
            format: RegistryArtifactFormat::CargoCrate,
            file_name: "callisto-model-1.2.3.crate".to_string(),
            provenance_policy: policy(),
        };
        let mut all_slots = slots(&release);
        all_slots.push(registry_slot.clone());
        let reverse_slot = ReleaseArtifactSlot::RegistryPackage {
            package: reverse_package.clone(),
            version: release.version.clone(),
            registry: registry.clone(),
            format: RegistryArtifactFormat::CargoCrate,
            file_name: "aaa-1.2.3.crate".to_string(),
            provenance_policy: policy(),
        };
        all_slots.push(reverse_slot.clone());
        let publish_registry = ReleaseOperationId::RegistryArtifactPublish {
            package,
            version: release.version.clone(),
            registry: registry.clone(),
            slot: registry_slot,
        };
        let reverse_publish_registry = ReleaseOperationId::RegistryArtifactPublish {
            package: reverse_package,
            version: release.version.clone(),
            registry,
            slot: reverse_slot,
        };
        let tag = ReleaseOperationId::ProductTag {
            release: release.clone(),
            tag: release.tag(),
        };
        let prepare = ReleaseOperationId::ForgePrepare {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        let mut operations = vec![
            ReleaseOperation::new(publish_registry.clone(), vec![]).unwrap(),
            // `cargo/aaa` depends on `cargo/callisto-model`: execution
            // order must differ from the tag's lexical prerequisite order.
            ReleaseOperation::new(reverse_publish_registry.clone(), vec![publish_registry.clone()]).unwrap(),
            // Deliberately reverse lexical input: construction must canonicalize it.
            ReleaseOperation::new(
                tag.clone(),
                vec![publish_registry.clone(), reverse_publish_registry.clone()],
            )
            .unwrap(),
            ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap(),
        ];
        for slot in &all_slots {
            if slot.release().is_some() {
                operations.push(
                    ReleaseOperation::new(
                        ReleaseOperationId::ArtifactUpload {
                            release: release.clone(),
                            slot: slot.clone(),
                        },
                        vec![prepare.clone()],
                    )
                    .unwrap(),
                );
            }
        }
        let mut upload_ids = operations
            .iter()
            .filter_map(|operation| {
                matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }).then_some(operation.id.clone())
            })
            .collect::<Vec<_>>();
        upload_ids.sort();
        let forge_publish = ReleaseOperationId::ForgePublish {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        operations.push(ReleaseOperation::new(forge_publish, upload_ids).unwrap());
        let edges: BTreeMap<_, _> = operations
            .iter()
            .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
            .collect();
        let order = stable_order(&edges).unwrap();
        let by_id: BTreeMap<_, _> = operations
            .into_iter()
            .map(|operation| (operation.id.clone(), operation))
            .collect();
        let intent = ReleaseIntent::new(
            release,
            commit(),
            vec![approved, reverse_approved],
            order.into_iter().map(|id| by_id[&id].clone()).collect(),
            all_slots,
        )
        .unwrap();
        assert_eq!(intent.registry_packages.len(), 2);
        let tag_operation = intent
            .operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
            .unwrap();
        assert_eq!(tag_operation.prerequisites[0], reverse_publish_registry);
        assert_eq!(tag_operation.prerequisites[1], publish_registry);
        assert!(matches!(
            intent.operations[0].id,
            ReleaseOperationId::RegistryArtifactPublish { ref package, .. } if package.name() == "callisto-model"
        ));
        assert!(matches!(
            intent.operations[1].id,
            ReleaseOperationId::RegistryArtifactPublish { ref package, .. } if package.name() == "aaa"
        ));
        let mut duplicate_identity_slots = intent.slots.clone();
        if let ReleaseArtifactSlot::RegistryPackage { package, file_name, .. } = duplicate_identity_slots
            .iter_mut()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { package, .. } if package.name() == "aaa"))
            .unwrap()
        {
            *package = ReleasePackageId::parse("cargo/callisto-model").unwrap();
            *file_name = "callisto-model-copy-1.2.3.crate".to_string();
        }
        // The full intent constructor rejects two filename-distinct slots
        // that collapse to one approved registry identity.
        let duplicate_slot = duplicate_identity_slots
            .iter()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { package, file_name, .. } if package.name() == "callisto-model" && file_name == "callisto-model-copy-1.2.3.crate"))
            .unwrap()
            .clone();
        let mut duplicate_operations = intent.operations.clone();
        let original_id = duplicate_operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::RegistryArtifactPublish { ref package, .. } if package.name() == "aaa"))
            .unwrap()
            .id
            .clone();
        let replacement_id = ReleaseOperationId::RegistryArtifactPublish {
            package: ReleasePackageId::parse("cargo/callisto-model").unwrap(),
            version: intent.product_release.version.clone(),
            registry: registry_binding(),
            slot: duplicate_slot,
        };
        duplicate_operations
            .iter_mut()
            .find(|operation| operation.id == original_id)
            .unwrap()
            .id = replacement_id.clone();
        for operation in &mut duplicate_operations {
            for prerequisite in &mut operation.prerequisites {
                if *prerequisite == original_id {
                    *prerequisite = replacement_id.clone();
                }
            }
            operation.prerequisites.sort();
        }
        assert!(matches!(
            ReleaseIntent::new(
                intent.product_release.clone(),
                intent.source_commit.clone(),
                intent.registry_packages.clone(),
                duplicate_operations,
                duplicate_identity_slots
            ),
            Err(SuccessorError::RegistrySlotOutsideApprovedRoster)
        ));
        let mut malformed = serde_json::to_value(&intent).unwrap();
        malformed["registryPackages"][0]["format"] = serde_json::Value::String("pythonWheel".to_string());
        assert!(serde_json::from_value::<ReleaseIntent>(malformed).is_err());
        assert!(ApprovedRegistryPackage::new(
            ReleasePackageId::parse("cargo/wrong").unwrap(),
            registry_binding(),
            RegistryArtifactFormat::NpmTarball,
        )
        .is_err());
    }

    #[test]
    fn product_identity_is_safe_semver_and_canonical() {
        assert!(ProductName::parse("Callisto").is_err());
        assert!(ProductName::parse("callisto/").is_err());
        assert_eq!(release().tag(), "callisto@1.2.3");
        assert!(ProductReleaseId::from_coordinated_versions(
            ProductName::parse("callisto").unwrap(),
            [Version::semver(1, 2, 3), Version::semver(1, 2, 4)],
        )
        .is_err());
        assert!(ProductReleaseId::new(
            ProductName::parse("callisto").unwrap(),
            Version::parse("1.2.3", VersionGrammar::Pep440).unwrap(),
        )
        .is_err());
        let wire = serde_json::to_value(release()).unwrap();
        assert!(serde_json::from_value::<ProductReleaseId>(wire).is_ok());
        assert_eq!(
            serde_json::to_string(&ProductTarget::X86_64UnknownLinuxMusl).unwrap(),
            "\"x86_64-unknown-linux-musl\""
        );
    }

    #[test]
    fn closed_roster_operations_and_wire_are_strict() {
        let intent = intent();
        assert_eq!(intent.slots.len(), 6);
        let mut wire = serde_json::to_value(&intent).unwrap();
        wire["unexpected"] = serde_json::Value::Bool(true);
        assert!(serde_json::from_value::<ReleaseIntent>(wire).is_err());
        let mut missing = intent.slots.clone();
        missing.pop();
        assert!(ReleaseIntent::new(
            intent.product_release.clone(),
            commit(),
            intent.registry_packages.clone(),
            intent.operations.clone(),
            missing
        )
        .is_err());
        let mut duplicate = intent.slots.clone();
        duplicate.push(duplicate[0].clone());
        assert!(ReleaseIntent::new(
            intent.product_release.clone(),
            commit(),
            intent.registry_packages.clone(),
            intent.operations.clone(),
            duplicate
        )
        .is_err());
        let mut wrong_target = intent.slots.clone();
        if let ReleaseArtifactSlot::ProductAsset { target, .. } = wrong_target
            .iter_mut()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
            .unwrap()
        {
            *target = ProductTarget::Wasm32Wasip1;
        }
        assert!(ReleaseIntent::new(
            intent.product_release.clone(),
            commit(),
            intent.registry_packages.clone(),
            intent.operations.clone(),
            wrong_target
        )
        .is_err());
        let mut unsafe_slot = intent.slots.clone();
        if let ReleaseArtifactSlot::ProductAsset { file_name, .. } = unsafe_slot
            .iter_mut()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
            .unwrap()
        {
            *file_name = "../callisto.tar.gz".to_string();
        }
        assert!(ReleaseIntent::new(
            intent.product_release.clone(),
            commit(),
            intent.registry_packages.clone(),
            intent.operations.clone(),
            unsafe_slot
        )
        .is_err());
        let mut fifth_target = intent.slots.clone();
        let fifth_slot = ReleaseArtifactSlot::ProductAsset {
            release: intent.product_release.clone(),
            target: ProductTarget::Aarch64AppleDarwin,
            file_name: "callisto-extra.tar.gz".to_string(),
            provenance_policy: policy(),
        };
        fifth_target.push(fifth_slot.clone());
        let prepare = intent
            .operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
            .unwrap()
            .id
            .clone();
        let fifth_upload = ReleaseOperation::new(
            ReleaseOperationId::ArtifactUpload {
                release: intent.product_release.clone(),
                slot: fifth_slot,
            },
            vec![prepare],
        )
        .unwrap();
        let mut fifth_operations = intent.operations.clone();
        let publish_index = fifth_operations
            .iter()
            .position(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
            .unwrap();
        fifth_operations[publish_index]
            .prerequisites
            .push(fifth_upload.id.clone());
        fifth_operations[publish_index].prerequisites.sort();
        fifth_operations.insert(publish_index, fifth_upload);
        assert!(matches!(
            ReleaseIntent::new(
                intent.product_release.clone(),
                commit(),
                intent.registry_packages.clone(),
                fifth_operations,
                fifth_target
            ),
            Err(SuccessorError::InvalidProductRoster)
        ));
        let mut malformed_policy = serde_json::to_value(&intent).unwrap();
        let slot = malformed_policy["slots"]
            .as_array_mut()
            .unwrap()
            .iter_mut()
            .find(|slot| slot["kind"] == "productAsset")
            .unwrap();
        assert!(slot.get("provenancePolicy").is_some());
        slot["provenancePolicy"]["githubAttestationRequired"] = serde_json::Value::Bool(false);
        let error = serde_json::from_value::<ReleaseIntent>(malformed_policy).unwrap_err();
        assert!(error.to_string().contains("artifact slot provenance is invalid"));
        let mut direct_policy = policy();
        direct_policy.github_attestation_required = false;
        assert!(matches!(
            direct_policy.validate(),
            Err(SuccessorError::InvalidProvenance)
        ));

