    fn slots(release: &ProductReleaseId) -> Vec<ReleaseArtifactSlot> {
        ProductTarget::ALL
            .iter()
            .map(|target| ReleaseArtifactSlot::ProductAsset {
                release: release.clone(),
                target: *target,
                file_name: format!("callisto-{target:?}.tar.gz"),
                provenance_policy: policy(),
            })
            .chain([
                ReleaseArtifactSlot::ChecksumManifest {
                    release: release.clone(),
                    file_name: CHECKSUM_FILE_NAME.to_string(),
                    provenance_policy: policy(),
                },
                ReleaseArtifactSlot::ReleaseMetadata {
                    release: release.clone(),
                    file_name: METADATA_FILE_NAME.to_string(),
                    provenance_policy: policy(),
                },
            ])
            .collect()
    }

    fn intent() -> ReleaseIntent {
        let release = release();
        let slots = slots(&release);
        let tag = ReleaseOperationId::ProductTag {
            release: release.clone(),
            tag: release.tag(),
        };
        let prepare = ReleaseOperationId::ForgePrepare {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        let uploads = slots
            .iter()
            .map(|slot| {
                ReleaseOperation::new(
                    ReleaseOperationId::ArtifactUpload {
                        release: release.clone(),
                        slot: slot.clone(),
                    },
                    vec![prepare.clone()],
                )
                .unwrap()
            })
            .collect::<Vec<_>>();
        let publish = ReleaseOperationId::ForgePublish {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        let mut prerequisites = uploads.iter().map(|operation| operation.id.clone()).collect::<Vec<_>>();
        prerequisites.sort();
        let mut operations = vec![
            ReleaseOperation::new(tag.clone(), vec![]).unwrap(),
            ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap(),
        ];
        operations.extend(uploads);
        operations.push(ReleaseOperation::new(publish, prerequisites).unwrap());
        operations.sort_by(|left, right| left.id.cmp(&right.id));
        // Rebuild in canonical DAG order: tag, prepare, all uploads, publish.
        let mut canonical = Vec::new();
        let tag = operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
            .cloned()
            .unwrap();
        let prepare = operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
            .cloned()
            .unwrap();
        canonical.push(tag);
        canonical.push(prepare);
        canonical.extend(
            operations
                .iter()
                .filter(|operation| matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }))
                .cloned(),
        );
        canonical.sort_by(|left, right| left.id.cmp(&right.id));
        // The stable order is identity sorted among all currently-ready nodes;
        // calculate it rather than baking a variant order into the test fixture.
        let edges: BTreeMap<_, _> = canonical
            .iter()
            .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
            .chain(std::iter::once((
                operations
                    .iter()
                    .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
                    .unwrap()
                    .id
                    .clone(),
                operations
                    .iter()
                    .find(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
                    .unwrap()
                    .prerequisites
                    .clone(),
            )))
            .collect();
        let ordered = stable_order(&edges).unwrap();
        let lookup: BTreeMap<_, _> = operations
            .into_iter()
            .chain(canonical)
            .map(|operation| (operation.id.clone(), operation))
            .collect();
        ReleaseIntent::new(
            release,
            commit(),
            vec![],
            ordered.into_iter().map(|id| lookup[&id].clone()).collect(),
            slots,
        )
        .unwrap()
    }

    fn registry_binding() -> RegistryBindingId {
        RegistryBindingId::new(
            "cratesIo",
            RegistryBindingDigest::from_normalized_binding("https://index.crates.io/"),
        )
        .unwrap()
    }

    #[test]
    fn approved_registry_roster_is_positive_and_feeds_the_product_tag() {
        let release = release();
        let registry = registry_binding();
        let package = ReleasePackageId::parse("cargo/callisto-model").unwrap();
        let approved =
            ApprovedRegistryPackage::new(package.clone(), registry.clone(), RegistryArtifactFormat::CargoCrate)
                .unwrap();
        let reverse_package = ReleasePackageId::parse("cargo/aaa").unwrap();
        let reverse_approved = ApprovedRegistryPackage::new(
            reverse_package.clone(),
            registry.clone(),
            RegistryArtifactFormat::CargoCrate,
        )
        .unwrap();
        assert_eq!(
            serde_json::from_value::<ApprovedRegistryPackage>(serde_json::to_value(&approved).unwrap()).unwrap(),
            approved
        );
        let mut malformed_approved = serde_json::to_value(&approved).unwrap();
        malformed_approved["format"] = serde_json::Value::String("pythonWheel".to_string());
        assert!(serde_json::from_value::<ApprovedRegistryPackage>(malformed_approved).is_err());
        let registry_slot = ReleaseArtifactSlot::RegistryPackage {
            package: package.clone(),
            version: release.version.clone(),
            registry: registry.clone(),
            format: RegistryArtifactFormat::CargoCrate,
            file_name: "callisto-model-1.2.3.crate".to_string(),
            provenance_policy: policy(),
        };
        let mut all_slots = slots(&release);
        all_slots.push(registry_slot.clone());
        let reverse_slot = ReleaseArtifactSlot::RegistryPackage {
            package: reverse_package.clone(),
            version: release.version.clone(),
            registry: registry.clone(),
            format: RegistryArtifactFormat::CargoCrate,
            file_name: "aaa-1.2.3.crate".to_string(),
            provenance_policy: policy(),
        };
        all_slots.push(reverse_slot.clone());
        let publish_registry = ReleaseOperationId::RegistryArtifactPublish {
            package,
            version: release.version.clone(),
            registry: registry.clone(),
            slot: registry_slot,
        };
        let reverse_publish_registry = ReleaseOperationId::RegistryArtifactPublish {
            package: reverse_package,
            version: release.version.clone(),
            registry,
            slot: reverse_slot,
        };
        let tag = ReleaseOperationId::ProductTag {
            release: release.clone(),
            tag: release.tag(),
        };
        let prepare = ReleaseOperationId::ForgePrepare {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        let mut operations = vec![
            ReleaseOperation::new(publish_registry.clone(), vec![]).unwrap(),
            // `cargo/aaa` depends on `cargo/callisto-model`: execution
            // order must differ from the tag's lexical prerequisite order.
            ReleaseOperation::new(reverse_publish_registry.clone(), vec![publish_registry.clone()]).unwrap(),
            // Deliberately reverse lexical input: construction must canonicalize it.
            ReleaseOperation::new(
                tag.clone(),
                vec![publish_registry.clone(), reverse_publish_registry.clone()],
            )
            .unwrap(),
            ReleaseOperation::new(prepare.clone(), vec![tag]).unwrap(),
        ];
        for slot in &all_slots {
            if slot.release().is_some() {
                operations.push(
                    ReleaseOperation::new(
                        ReleaseOperationId::ArtifactUpload {
                            release: release.clone(),
                            slot: slot.clone(),
                        },
                        vec![prepare.clone()],
                    )
                    .unwrap(),
                );
            }
        }
        let mut upload_ids = operations
            .iter()
            .filter_map(|operation| {
                matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }).then_some(operation.id.clone())
            })
            .collect::<Vec<_>>();
        upload_ids.sort();
        let forge_publish = ReleaseOperationId::ForgePublish {
            release: release.clone(),
            repository: GitHubRepository::parse("callisto-rs/callisto").unwrap(),
        };
        operations.push(ReleaseOperation::new(forge_publish, upload_ids).unwrap());
        let edges: BTreeMap<_, _> = operations
            .iter()
            .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
            .collect();
        let order = stable_order(&edges).unwrap();
        let by_id: BTreeMap<_, _> = operations
            .into_iter()
            .map(|operation| (operation.id.clone(), operation))
            .collect();
        let intent = ReleaseIntent::new(
            release,
            commit(),
            vec![approved, reverse_approved],
            order.into_iter().map(|id| by_id[&id].clone()).collect(),
            all_slots,
        )
        .unwrap();
        assert_eq!(intent.registry_packages.len(), 2);
        let tag_operation = intent
            .operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
            .unwrap();
        assert_eq!(tag_operation.prerequisites[0], reverse_publish_registry);
        assert_eq!(tag_operation.prerequisites[1], publish_registry);
        assert!(matches!(
            intent.operations[0].id,
            ReleaseOperationId::RegistryArtifactPublish { ref package, .. } if package.name() == "callisto-model"
        ));
        assert!(matches!(
            intent.operations[1].id,
            ReleaseOperationId::RegistryArtifactPublish { ref package, .. } if package.name() == "aaa"
        ));
        let mut duplicate_identity_slots = intent.slots.clone();
        if let ReleaseArtifactSlot::RegistryPackage { package, file_name, .. } = duplicate_identity_slots
            .iter_mut()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { package, .. } if package.name() == "aaa"))
            .unwrap()
        {
            *package = ReleasePackageId::parse("cargo/callisto-model").unwrap();
            *file_name = "callisto-model-copy-1.2.3.crate".to_string();
        }
        // The full intent constructor rejects two filename-distinct slots
        // that collapse to one approved registry identity.
        let duplicate_slot = duplicate_identity_slots
            .iter()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { package, file_name, .. } if package.name() == "callisto-model" && file_name == "callisto-model-copy-1.2.3.crate"))
            .unwrap()
            .clone();
        let mut duplicate_operations = intent.operations.clone();
        let original_id = duplicate_operations
            .iter()
            .find(|operation| matches!(operation.id, ReleaseOperationId::RegistryArtifactPublish { ref package, .. } if package.name() == "aaa"))
            .unwrap()
            .id
            .clone();
        let replacement_id = ReleaseOperationId::RegistryArtifactPublish {
            package: ReleasePackageId::parse("cargo/callisto-model").unwrap(),
            version: intent.product_release.version.clone(),
            registry: registry_binding(),
            slot: duplicate_slot,
        };
        duplicate_operations
            .iter_mut()
            .find(|operation| operation.id == original_id)
            .unwrap()
            .id = replacement_id.clone();
        for operation in &mut duplicate_operations {
            for prerequisite in &mut operation.prerequisites {
                if *prerequisite == original_id {
                    *prerequisite = replacement_id.clone();
                }
            }
            operation.prerequisites.sort();
        }
        assert!(matches!(
            ReleaseIntent::new(
                intent.product_release.clone(),
                intent.source_commit.clone(),
                intent.registry_packages.clone(),
                duplicate_operations,
                duplicate_identity_slots
            ),
            Err(SuccessorError::RegistrySlotOutsideApprovedRoster)
        ));
        let mut malformed = serde_json::to_value(&intent).unwrap();
        malformed["registryPackages"][0]["format"] = serde_json::Value::String("pythonWheel".to_string());
        assert!(serde_json::from_value::<ReleaseIntent>(malformed).is_err());
        assert!(ApprovedRegistryPackage::new(
            ReleasePackageId::parse("cargo/wrong").unwrap(),
            registry_binding(),
            RegistryArtifactFormat::NpmTarball,
        )
        .is_err());
    }

