                        ReleaseOperationId::ForgePrepare { release, .. } => ReleaseObservationEvidence::ForgePrepare {
                            schema_version: 1,
                            release: release.clone(),
                            lifecycle: ForgePrepareLifecycle::Draft,
                        },
                        ReleaseOperationId::ForgePublish { release, .. } => ReleaseObservationEvidence::ForgePublish {
                            schema_version: 1,
                            release: release.clone(),
                            asset_roster_digest: expected.asset_roster_digest.clone(),
                        },
                        ReleaseOperationId::ArtifactUpload { release, slot } => {
                            ReleaseObservationEvidence::ForgeAsset {
                                schema_version: 1,
                                release: release.clone(),
                                slot: slot.clone(),
                                digest: expected.entries[slot].0.clone(),
                                byte_length: expected.entries[slot].1,
                            }
                        }
                        ReleaseOperationId::RegistryArtifactPublish {
                            package,
                            version,
                            registry,
                            slot,
                        } => ReleaseObservationEvidence::RegistryArtifact {
                            schema_version: 1,
                            package: package.clone(),
                            version: version.clone(),
                            registry: registry.clone(),
                            slot: slot.clone(),
                            digest: ArtifactDigest::from_bytes(slot.file_name()),
                            byte_length: 1,
                        },
                    },
                    provenance: if index == 0 {
                        ObservationProvenance::NewlyProduced
                    } else {
                        ObservationProvenance::AlreadyPresent
                    },
                })
                .collect::<Vec<_>>();
            let receipt = CompleteObservationReceipt::new(&intent, &expected, operations).unwrap();
            assert!(receipt.validate_for_intent(&intent, &expected).is_ok());
            assert_eq!(
                serde_json::from_value::<CompleteObservationReceipt>(serde_json::to_value(&receipt).unwrap()).unwrap(),
                receipt
            );
            let mut unknown = serde_json::to_value(&receipt).unwrap();
            unknown["unexpected"] = serde_json::Value::Bool(true);
            assert!(serde_json::from_value::<CompleteObservationReceipt>(unknown).is_err());
            let mut missing = receipt.operations.clone();
            missing.pop();
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, &expected, missing),
                Err(SuccessorError::MismatchedObservationRoster)
            ));
            let mut reordered = receipt.operations.clone();
            reordered.swap(0, 1);
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, &expected, reordered),
                Err(SuccessorError::MismatchedObservationRoster)
            ));
            let mut wrong = receipt.operations.clone();
            wrong[0].evidence = ReleaseObservationEvidence::ForgePrepare {
                schema_version: 1,
                release: intent.product_release.clone(),
                lifecycle: ForgePrepareLifecycle::Draft,
            };
            assert!(matches!(
                CompleteObservationReceipt::new(&intent, &expected, wrong),
                Err(SuccessorError::MismatchedObservationEvidence)
            ));
        }
    }
}

