    #[test]
    fn artifact_upload_ids_differing_only_by_attestation_policy_stay_distinct_under_ord() {
        let package = ReleasePackageId::parse("cargo/demo").unwrap();
        let version = Version::semver(1, 0, 0);
        let slot_a = ArtifactSlotId::new(
            package.clone(),
            version.clone(),
