+            fixture.assert_evidence_rejected(prepare_as_publish);
+
+            let mut publish_as_prepare = fixture.operations.clone();
+            publish_as_prepare[publish].evidence = ReleaseObservationEvidence::ForgePrepare {
+                schema_version: 1,
+                release: fixture.intent.product_release.clone(),
+                lifecycle: ForgePrepareLifecycle::PublishedSuccessor,
+            };
+            fixture.assert_evidence_rejected(publish_as_prepare);
+        }
