+        #[test]
+        fn observation_expectations_reject_a_manifest_from_another_intent() {
+            let intent = intent();
+            let other_intent = intent_with_source_and_registry(CommitSha::parse(&"b".repeat(40)).unwrap(), false);
+            let other_manifest = manifest_for(&other_intent);
             assert!(matches!(
-                CompleteObservationReceipt::new(&intent, &expected, wrong),
-                Err(SuccessorError::MismatchedObservationEvidence)
+                ObservationExpectations::from_manifest(&intent, &other_manifest),
+                Err(SuccessorError::MismatchedManifest)
             ));
         }
+
+        #[test]
+        fn every_github_asset_independently_affects_and_gates_the_roster_digest() {
+            let fixture = observation_fixture(false);
+            assert_eq!(fixture.manifest.entries.len(), 6);
+            assert_eq!(asset_roster_digest(&fixture.manifest.entries), fixture.expected.asset_roster_digest);
+            let publish = fixture.operation_index(|id| matches!(id, ReleaseOperationId::ForgePublish { .. }));
+
+            for index in 0..fixture.manifest.entries.len() {
+                let mut changed_entries = fixture.manifest.entries.clone();
+                changed_entries[index].byte_length += 1;
+                let changed_digest = asset_roster_digest(&changed_entries);
+                assert_ne!(changed_digest, fixture.expected.asset_roster_digest);
+
+                let mut operations = fixture.operations.clone();
+                let ReleaseObservationEvidence::ForgePublish {
+                    asset_roster_digest,
+                    ..
+                } = &mut operations[publish].evidence
+                else {
+                    unreachable!();
+                };
+                *asset_roster_digest = changed_digest;
+                fixture.assert_evidence_rejected(operations);
+            }
+        }
+
+        #[test]
+        fn observation_wire_uses_canonical_camel_case_keys_only() {
+            let fixture = observation_fixture(true);
+            let wire = serde_json::to_value(fixture.receipt()).unwrap();
+            assert_no_snake_case_keys(&wire);
+            assert!(wire.get("schemaVersion").is_some());
+            assert!(wire.get("intentDigest").is_some());
+            assert!(wire.get("schema_version").is_none());
+            assert!(wire.get("intent_digest").is_none());
+
+            let evidence = wire["operations"].as_array().unwrap();
+            assert!(evidence.iter().any(|entry| {
+                entry["evidence"].get("registryKey").is_some()
+                    && entry["evidence"].get("bindingDigest").is_some()
+                    && entry["evidence"].get("byteLength").is_some()
+            }));
+            assert!(evidence
+                .iter()
+                .any(|entry| entry["evidence"].get("annotationDigest").is_some()));
+            assert!(evidence
+                .iter()
+                .any(|entry| entry["evidence"].get("assetRosterDigest").is_some()));
+        }
